const POR_ID = new Map([...CRITERIOS, ...REGRAS].map((c) => [c.id, c]));

/** Critério ou regra pelo id (undefined se não existir). */
export function criterio(id) { return POR_ID.get(id); }

/**
 * Família usada nas faixas: 'ativo-fii' -> 'fiis', 'ativo-rf' -> 'rf' etc.
 * `subtipo` ('pos' | 'ipca' | 'pre') refina renda fixa ('rf-pos', 'rf-ipca').
 */
export function familiaDaClasse(classe, subtipo = null) {
  const c = String(classe || '').toLowerCase();
  const base = ({ 'ativo-acao': 'acoes', 'ativo-fii': 'fiis', 'ativo-eua': 'eua', 'ativo-rf': 'rf' })[c] || c;
  if (base === 'rf' && subtipo) return subtipo === 'pos' ? 'rf-pos' : 'rf-ipca';
  return base || null;
}

/** Limites numéricos [bom, neutro, atencao] de um critério pra família (com fallback rf-pos -> rf -> padrao). */
export function limites(id, familia) {
  const c = POR_ID.get(id);
  if (!c || !c.limites) return null;
  const f = familia || 'padrao';
  return c.limites[f] || (f.startsWith('rf-') && c.limites.rf) || c.limites.padrao || null;
}

/**
 * Classifica um valor nas faixas do critério: 'bom' | 'neutro' | 'atencao' | 'ruim'.
 * direção "maior": >= bom -> bom; >= neutro -> neutro; >= atencao -> atencao; senão ruim.
 * direção "menor": <= bom -> bom; <= neutro -> neutro; <= atencao -> atencao; senão ruim.
 * direção "proximo": |valor| na régua "menor".
 */
export function classificar(id, valor, familia) {
  const c = POR_ID.get(id);
  const l = limites(id, familia);
  if (!c || !l || typeof valor !== 'number' || !Number.isFinite(valor)) return null;
  const dir = c.direcao === 'proximo' ? 'menor' : c.direcao;
  const v = c.direcao === 'proximo' ? Math.abs(valor) : valor;
  if (dir === 'menor') return v <= l[0] ? 'bom' : v <= l[1] ? 'neutro' : v <= l[2] ? 'atencao' : 'ruim';
  return v >= l[0] ? 'bom' : v >= l[1] ? 'neutro' : v >= l[2] ? 'atencao' : 'ruim';
}

/** Prazo mínimo (meses) pra julgar uma família - abaixo disso, tom neutro. */
export function mesesParaJulgar(familia) {
  const p = PRAZOS_MINIMOS[familia] || PRAZOS_MINIMOS[String(familia || '').replace(/-.*$/, '')];
  return p ? p[1] : 12;
}

/** Fontes (sem repetir url) de uma lista de ids de critérios/regras. */
export function fontesDosCriterios(ids) {
  const vistos = new Set();
  const out = [];
  (ids || []).forEach((id) => {
    const c = POR_ID.get(id);
    (c ? c.fontes : []).forEach((f) => { if (!vistos.has(f.url)) { vistos.add(f.url); out.push(f); } });
  });
  return out;
}

/** Preenche {placeholders} de uma frase da base. */
export function preencherFrase(modelo, valores) {
  return String(modelo || '').replace(/\{(\w+)\}/g, (m, k) => (valores && valores[k] != null ? String(valores[k]) : m));
}
